<?php

declare(strict_types=1);

namespace LaraSlice\Tests\Feature\Core;

use Illuminate\Foundation\Application;
use LaraSlice\Core\Discovery\SliceManager;
use LaraSlice\Core\Discovery\SliceManifest;
use LaraSlice\Tests\TestCase;

/**
 * slice:repair's template-upgrade pass brings blades generated by
 * older templates up to the current hooks (validation banner,
 * overlay grid markers, declared-view toolbar buttons, timer +
 * declared-stats on show pages) — marker-guarded and idempotent —
 * and discoveredSlices() must include name-shadowed twins, whose
 * pages are live even though the registry key belongs to a twin.
 */
final class RepairTemplateUpgradeTest extends TestCase
{
    private string $root;

    protected function setUp(): void
    {
        parent::setUp();
        $this->root = sys_get_temp_dir().'/ls-repair-'.uniqid();
        mkdir($this->root.'/Old/Resources/views', 0777, true);
        file_put_contents($this->root.'/Old/slice.yaml', "name: 'Old'\nversion: 1.0.0\n");
        file_put_contents($this->root.'/Old/Resources/views/form.blade.php', <<<'BLADE'
<div class="w-full max-w-5xl mx-auto space-y-6">
    <form action="/old" method="POST" class="space-y-6">
        @csrf
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
            <input name="title" />
        </div>
    </form>
</div>
BLADE);
        file_put_contents($this->root.'/Old/Resources/views/index.blade.php', <<<'BLADE'
<div>
    @php
        $dirUi = $manifest['ui']['directory'] ?? [];
        $tableViews = $dirUi['views'] ?? ['table'];
        $defaultView = $dirUi['default_view'] ?? 'table';
        $inlineEdit = $dirUi['inline_edit'] ?? [];
    @endphp
    @if($can['create'] ?? true)
    <span>Add Old</span>
    @endif
</div>
BLADE);
        file_put_contents($this->root.'/Old/Resources/views/show.blade.php', <<<'BLADE'
<div x-data="{ activeTab: 'overview' }">
    <div x-show="activeTab === 'overview'" x-transition class="space-y-6">
        <p>details</p>
    </div>
</div>
BLADE);
    }

    protected function tearDown(): void
    {
        $this->removeTree($this->root);
        parent::tearDown();
    }

    private function removeTree(string $dir): void
    {
        if (! is_dir($dir)) {
            return;
        }
        foreach (scandir($dir) ?: [] as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            $path = $dir.'/'.$entry;
            is_dir($path) ? $this->removeTree($path) : unlink($path);
        }
        rmdir($dir);
    }

    public function test_repair_upgrades_old_templates_and_is_idempotent(): void
    {
        $manager = new SliceManager($this->app instanceof Application ? $this->app : app());
        $slice = new SliceManifest($this->root.'/Old/slice.yaml');

        $changed = $manager->repairSlice($slice);
        $this->assertNotSame([], $changed);

        $form = file_get_contents($this->root.'/Old/Resources/views/form.blade.php');
        $this->assertStringContainsString('$errors->any()', $form);
        $this->assertStringContainsString('Please fix the following:', $form);
        $this->assertStringContainsString('data-ls-section-grid', $form);
        $this->assertStringContainsString('data-ls-form-root', $form);

        $index = file_get_contents($this->root.'/Old/Resources/views/index.blade.php');
        // (e) controller-preference: stale unconditional assignments
        // become ??-guarded so controller-passed values win.
        $this->assertStringContainsString('$tableViews = $tableViews ?? $dirUi[\'views\'] ?? [\'table\'];', $index);
        $this->assertStringContainsString('$defaultView = $defaultView ?? $dirUi[\'default_view\'] ?? \'table\';', $index);
        $this->assertStringContainsString('$inlineEdit = $inlineEdit ?? $dirUi[\'inline_edit\'] ?? [];', $index);
        $this->assertStringContainsString('$matrixUrl', $index);
        $this->assertStringContainsString('$bulkEntryUrl', $index);
        $this->assertStringContainsString('$reportUrl', $index);

        $show = file_get_contents($this->root.'/Old/Resources/views/show.blade.php');
        $this->assertStringContainsString('partials.timer-card', $show);
        $this->assertStringContainsString('$showStats', $show);

        // Second run changes nothing.
        $this->assertSame([], $manager->repairSlice($slice));
    }

    public function test_discovered_slices_include_shadowed_twins(): void
    {
        $manager = new SliceManager($this->app instanceof Application ? $this->app : app());
        $register = new \ReflectionMethod($manager, 'registerManifest');
        $register->setAccessible(true);

        mkdir($this->root.'/A/EmailTemplates', 0777, true);
        mkdir($this->root.'/B/EmailTemplates', 0777, true);
        file_put_contents($this->root.'/A/EmailTemplates/slice.yaml', "name: 'Email Templates'\n");
        file_put_contents($this->root.'/B/EmailTemplates/slice.yaml', "name: 'EmailTemplates'\n");
        $register->invoke($manager, new SliceManifest($this->root.'/A/EmailTemplates/slice.yaml'));
        $register->invoke($manager, new SliceManifest($this->root.'/B/EmailTemplates/slice.yaml'));

        $this->assertCount(2, $manager->discoveredSlices());
        $this->assertCount(1, $manager->nameCollisions());
    }
}
